const sources=["# MATHÉMATIQUES — 6e\n\n## Chapitre 6 — Fractions\n\n**Volume horaire : 7 heures**\n\n---\n\n# 🎯 OBJECTIFS D'APPRENTISSAGE\n\nÀ la fin de ce chapitre, l'élève doit être capable de :\n\n-  comprendre le sens d'une fraction ; \n-  identifier le numérateur et le dénominateur ; \n-  lire et écrire une fraction ; \n-  représenter une fraction ; \n-  déterminer une fraction d'une quantité ; \n-  reconnaître une fraction égale à 1 ; \n-  reconnaître une fraction inférieure ou supérieure à 1 ; \n-  comparer des fractions simples ; \n-  reconnaître des fractions équivalentes simples ; \n-  placer des fractions simples sur une droite graduée ; \n-  résoudre des problèmes faisant intervenir des fractions. \n\n---\n\n# 1. 📖 COURS\n\n## 1.1. Qu'est-ce qu'une fraction ?\n\nUne **fraction** permet de représenter une ou plusieurs parties égales d'un tout.\n\nImaginons une tablette de chocolat divisée en **4 parts égales**.\n\nSi on prend une part, on prend :\n\n**1/4**\n\nSi on prend trois parts :\n\n**3/4**\n\nLa fraction permet donc de représenter une quantité qui n'est pas nécessairement un nombre entier.\n\n---\n\n# 1.2. Écriture d'une fraction\n\nUne fraction s'écrit sous la forme :\n\n**a/b**\n\navec **b ≠ 0**.\n\nDans :\n\n**3/5**\n\nle nombre **3** est appelé le **numérateur**.\n\nLe nombre **5** est appelé le **dénominateur**.\n\n### À retenir\n\n**Numérateur → nombre de parts prises**\n\n**Dénominateur → nombre total de parts égales**\n\n---\n\n# 1.3. Exemple concret\n\nUne pizza est découpée en **8 parts égales**.\n\nUn élève mange **3 parts**.\n\nLa fraction de pizza mangée est :\n\n**3/8**\n\nLa fraction restante est :\n\n**5/8**\n\ncar :\n\n**8/8 − 3/8 = 5/8**\n\n---\n\n# 1.4. Lire une fraction\n\nVoici quelques exemples :\n\n| Fraction | Lecture          |\n| -------- | ---------------- |\n| 1/2      | un demi          |\n| 1/3      | un tiers         |\n| 1/4      | un quart         |\n| 2/5      | deux cinquièmes  |\n| 3/7      | trois septièmes  |\n| 4/8      | quatre huitièmes |\n| 7/10     | sept dixièmes    |\n\n---\n\n# 1.5. Fraction inférieure à 1\n\nUne fraction est inférieure à 1 lorsque son numérateur est inférieur à son dénominateur.\n\n### Exemple\n\n**3/5 < 1**\n\ncar :\n\n**3 < 5**\n\nDe même :\n\n**2/7 < 1**\n\n---\n\n# 1.6. Fraction égale à 1\n\nUne fraction est égale à 1 lorsque son numérateur et son dénominateur sont égaux.\n\n### Exemple\n\n**5/5 = 1**\n\n**8/8 = 1**\n\n**100/100 = 1**\n\n---\n\n# 1.7. Fraction supérieure à 1\n\nUne fraction est supérieure à 1 lorsque son numérateur est supérieur à son dénominateur.\n\n### Exemple\n\n**7/4 > 1**\n\ncar :\n\n**7 > 4**\n\nCela signifie que la fraction représente plus qu'une unité entière.\n\n---\n\n# 1.8. Représenter une fraction\n\nPour représenter **3/4** :\n\n1.  on divise une unité en 4 parties égales ; \n2.  on prend 3 de ces parties. \n\nLa fraction **3/4** représente donc trois quarts de l'unité.\n\n⚠️ Les parties doivent toujours être **égales**.\n\nDiviser une figure en quatre parties de tailles différentes ne permet pas de représenter correctement des quarts.\n\n---\n\n# 1.9. Fraction d'une quantité\n\nUne fraction peut également représenter une partie d'une quantité.\n\n### Exemple\n\nCalculons **1/4 de 20**.\n\nOn divise 20 par 4 :\n\n**20 ÷ 4 = 5**\n\nDonc :\n\n**1/4 de 20 = 5**\n\n---\n\n### Exemple\n\nCalculons **3/4 de 20**.\n\nOn commence par calculer :\n\n**20 ÷ 4 = 5**\n\nPuis :\n\n**5 × 3 = 15**\n\nDonc :\n\n**3/4 de 20 = 15**\n\n### Méthode\n\nPour calculer une fraction d'une quantité :\n\n**1. On divise par le dénominateur.**\n\n**2. On multiplie par le numérateur.**\n\n---\n\n# 1.10. Autre exemple\n\nCalculons :\n\n**2/5 de 30**\n\nÉtape 1 :\n\n**30 ÷ 5 = 6**\n\nÉtape 2 :\n\n**6 × 2 = 12**\n\nDonc :\n\n**2/5 de 30 = 12**\n\n---\n\n# 1.11. Fractions équivalentes\n\nDeux fractions peuvent être écrites différemment tout en représentant la même quantité.\n\n### Exemple\n\n**1/2 = 2/4**\n\nEn effet, la moitié d'une quantité est identique à deux quarts.\n\nOn peut également avoir :\n\n**1/2 = 3/6 = 4/8**\n\nCes fractions sont **équivalentes**.\n\n---\n\n# 1.12. Obtenir une fraction équivalente\n\nOn peut multiplier le numérateur et le dénominateur par un même nombre non nul.\n\n### Exemple\n\nÀ partir de :\n\n**2/3**\n\nmultiplions par 2 :\n\n**(2 × 2)/(3 × 2) = 4/6**\n\nDonc :\n\n**2/3 = 4/6**\n\n---\n\n# 1.13. Comparer des fractions ayant le même dénominateur\n\nLorsque deux fractions ont le même dénominateur, on compare leurs numérateurs.\n\n### Exemple\n\nComparer :\n\n**3/7 et 5/7**\n\nLes dénominateurs sont identiques.\n\nOn compare :\n\n**3 et 5**\n\nComme :\n\n**3 < 5**\n\nalors :\n\n**3/7 < 5/7**\n\n---\n\n# 1.14. Comparer des fractions ayant le même numérateur\n\nLorsque deux fractions positives ont le même numérateur, **la fraction qui possède le plus petit dénominateur est la plus grande**.\n\n### Exemple\n\nComparer :\n\n**3/4 et 3/7**\n\nLe numérateur est le même.\n\nComme 4 est inférieur à 7 :\n\n**3/4 > 3/7**\n\n---\n\n# 1.15. Fraction et nombre entier\n\nTout nombre entier peut être écrit sous forme de fraction de dénominateur 1.\n\n### Exemple\n\n**5 = 5/1**\n\n**8 = 8/1**\n\nOn peut également écrire :\n\n**3 = 6/2 = 9/3**\n\n---\n\n# 1.16. Placer une fraction sur une droite graduée\n\nPour placer une fraction comme **3/4** :\n\n1.  on considère une unité ; \n2.  on divise l'unité en 4 parties égales ; \n3.  on compte 3 graduations à partir de 0. \n\nOn arrive au point correspondant à :\n\n**3/4**\n\n---\n\n# 1.17. Fractions et partage\n\nLes fractions sont très utiles pour partager équitablement.\n\n### Exemple\n\nUne classe compte **24 élèves**.\n\nOn veut répartir les élèves en **4 groupes égaux**.\n\nChaque groupe représente :\n\n**1/4 de la classe**\n\nNombre d'élèves par groupe :\n\n**24 ÷ 4 = 6**\n\nChaque groupe contient donc **6 élèves**.\n\n---\n\n# 1.18. Fractions dans la vie quotidienne\n\nOn rencontre les fractions dans de nombreuses situations :\n\n-  recettes de cuisine ; \n-  partage d'une somme d'argent ; \n-  partage d'une tablette de chocolat ; \n-  temps ; \n-  distances ; \n-  résultats sportifs ; \n-  proportions ; \n-  surfaces. \n\n### Exemple\n\nUne recette nécessite **3/4 de litre** de lait.\n\nCela signifie trois parts d'un litre partagé en quatre parts égales.\n\n---\n\n# 🧠 À RETENIR\n\nUne fraction s'écrit :\n\n**a/b**\n\navec **b ≠ 0**.\n\nDans **3/5** :\n\n-  3 = numérateur ; \n-  5 = dénominateur. \n\n### Types de fractions\n\n**3/5 < 1**\n\n**5/5 = 1**\n\n**7/5 > 1**\n\n### Fraction d'une quantité\n\nPour calculer **3/5 de 20** :\n\n**20 ÷ 5 × 3 = 12**\n\n### Fractions équivalentes\n\n**1/2 = 2/4 = 3/6**\n\n### Comparaison\n\nMême dénominateur → comparer les numérateurs.\n\n---\n\n# ✏️ 2. EXERCICES D'APPLICATION\n\n## Exercice 1 — Numérateur et dénominateur\n\nDans chaque fraction, indique le numérateur et le dénominateur.\n\na) 3/7\n\nb) 5/9\n\nc) 8/11\n\nd) 4/5\n\ne) 9/10\n\n---\n\n## Exercice 2 — Lecture\n\nÉcris en lettres :\n\na) 1/2\n\nb) 3/4\n\nc) 2/5\n\nd) 7/8\n\ne) 9/10\n\n---\n\n## Exercice 3 — Écriture\n\nÉcris sous forme de fraction :\n\na) trois quarts\n\nb) deux cinquièmes\n\nc) cinq sixièmes\n\nd) sept dixièmes\n\n---\n\n## Exercice 4 — Comparer à 1\n\nIndique si chaque fraction est :\n\n-  inférieure à 1 ; \n-  égale à 1 ; \n-  supérieure à 1. \n\na) 3/5\n\nb) 7/7\n\nc) 9/4\n\nd) 2/8\n\ne) 11/10\n\n---\n\n## Exercice 5 — Fraction d'une quantité\n\nCalcule :\n\na) 1/2 de 20\n\nb) 1/4 de 28\n\nc) 2/3 de 18\n\nd) 3/5 de 25\n\ne) 4/7 de 35\n\n---\n\n# 🔵 3. RENFORCEMENT\n\n## Exercice 6 — Fractions équivalentes\n\nComplète :\n\na) 1/2 = .../4\n\nb) 2/3 = .../6\n\nc) 3/5 = .../10\n\nd) 4/7 = .../14\n\n---\n\n## Exercice 7 — Comparaison\n\nCompare avec **<, > ou =** :\n\na) 3/8 ... 5/8\n\nb) 7/10 ... 2/10\n\nc) 4/6 ... 4/9\n\nd) 5/5 ... 1\n\ne) 9/4 ... 2\n\n---\n\n## Exercice 8\n\nUne classe compte **36 élèves**.\n\n**2/3** des élèves participent à une activité sportive.\n\nCombien d'élèves participent à cette activité ?\n\n---\n\n## Exercice 9\n\nUn commerçant possède **60 tablettes de chocolat**.\n\nIl vend **3/5** de son stock.\n\n1.  Combien de tablettes vend-il ? \n2.  Combien de tablettes lui reste-t-il ? \n\n---\n\n# 🔴 4. PROBLÈMES\n\n## Problème 1 — Le chocolat\n\nUne tablette est divisée en **12 morceaux égaux**.\n\nPatrick mange **5 morceaux**.\n\n1.  Quelle fraction de la tablette a-t-il mangée ? \n2.  Quelle fraction reste-t-il ? \n3.  S'il y avait 24 morceaux au départ, combien en resterait-il après avoir mangé la même fraction ? \n\n---\n\n## Problème 2 — Une classe\n\nUne classe compte **40 élèves**.\n\n**3/8** des élèves pratiquent le football.\n\n1.  Combien d'élèves pratiquent le football ? \n2.  Combien d'élèves ne pratiquent pas le football ? \n\n---\n\n## Problème 3 — Une recette\n\nPour préparer une recette, il faut :\n\n**3/4 kg de chocolat**\n\nLe chocolatier possède **2 kg**.\n\n1.  Quelle quantité de chocolat reste-t-il après préparation ? \n2.  Exprime cette quantité en kilogrammes sous forme de fraction. \n\n---\n\n# 📝 5. QCM\n\n### Question 1\n\nDans la fraction **3/8**, le numérateur est :\n\nA. 3\n\nB. 8\n\nC. 11\n\nD. 5\n\n**Réponse : A**\n\n---\n\n### Question 2\n\nDans **5/9**, le dénominateur est :\n\nA. 5\n\nB. 9\n\nC. 14\n\nD. 4\n\n**Réponse : B**\n\n---\n\n### Question 3\n\nLaquelle de ces fractions est inférieure à 1 ?\n\nA. 7/4\n\nB. 5/5\n\nC. 3/8\n\nD. 9/6\n\n**Réponse : C**\n\n---\n\n### Question 4\n\nQuelle fraction est égale à 1 ?\n\nA. 3/4\n\nB. 5/5\n\nC. 2/7\n\nD. 8/9\n\n**Réponse : B**\n\n---\n\n### Question 5\n\nCombien vaut **1/4 de 20** ?\n\nA. 4\n\nB. 5\n\nC. 10\n\nD. 15\n\n**Réponse : B**\n\n---\n\n### Question 6\n\nCombien vaut **3/5 de 20** ?\n\nA. 8\n\nB. 10\n\nC. 12\n\nD. 15\n\n**Réponse : C**\n\n---\n\n### Question 7\n\nQuelle fraction est équivalente à **1/2** ?\n\nA. 2/3\n\nB. 2/4\n\nC. 3/5\n\nD. 4/6\n\n**Réponse : B**\n\n---\n\n### Question 8\n\nCompare :\n\n**3/7 ... 5/7**\n\nA. >\n\nB. <\n\nC. =\n\nD. Impossible\n\n**Réponse : B**\n\n---\n\n# ✅ 6. CORRECTION EXPLIQUÉE DU QCM\n\n### Q1 → A\n\nDans une fraction, le nombre placé au-dessus de la barre est le **numérateur**.\n\n**3/8 → numérateur = 3**\n\n### Q2 → B\n\nLe nombre placé sous la barre est le **dénominateur**.\n\n**5/9 → dénominateur = 9**\n\n### Q3 → C\n\nUne fraction est inférieure à 1 lorsque son numérateur est inférieur à son dénominateur.\n\n**3 < 8**, donc :\n\n**3/8 < 1**\n\n### Q4 → B\n\nLorsque le numérateur et le dénominateur sont égaux :\n\n**5/5 = 1**\n\n### Q5 → B\n\n**20 ÷ 4 = 5**\n\nDonc :\n\n**1/4 de 20 = 5**\n\n### Q6 → C\n\n**20 ÷ 5 = 4**\n\nPuis :\n\n**4 × 3 = 12**\n\nDonc :\n\n**3/5 de 20 = 12**\n\n### Q7 → B\n\n**1/2 = 2/4**\n\nLes deux fractions représentent la même quantité.\n\n### Q8 → B\n\nLes dénominateurs sont identiques. On compare donc les numérateurs :\n\n**3 < 5**\n\nDonc :\n\n**3/7 < 5/7**\n\n---\n\n# 📋 7. FICHE MÉMO\n\n## 🧠 FRACTIONS — 6e\n\n### Écriture\n\n**a/b**\n\n### Vocabulaire\n\n**a** → numérateur\n\n**b** → dénominateur\n\n### Comparaison avec 1\n\nNumérateur < dénominateur :\n\n**fraction < 1**\n\nNumérateur = dénominateur :\n\n**fraction = 1**\n\nNumérateur > dénominateur :\n\n**fraction > 1**\n\n### Fraction d'une quantité\n\n**a/b de N = N ÷ b × a**\n\n### Exemple\n\n**3/4 de 20**\n\n**20 ÷ 4 × 3 = 15**\n\n### Fractions équivalentes\n\n**1/2 = 2/4 = 3/6 = 4/8**\n\n### Même dénominateur\n\n**3/7 < 5/7**\n\ncar **3 < 5**.\n\n---\n\n# 🎮 8. QUIZ — TEST RAPIDE\n\n### Question 1\n\nDans **7/10**, quel est le numérateur ?\n\n➡️ **7**\n\n### Question 2\n\nDans **7/10**, quel est le dénominateur ?\n\n➡️ **10**\n\n### Question 3\n\n**4/4** est égal à combien ?\n\n➡️ **1**\n\n### Question 4\n\n**3/8** est-il inférieur ou supérieur à 1 ?\n\n➡️ **Inférieur à 1**\n\n### Question 5\n\nCalcule **1/5 de 30**.\n\n➡️ **6**\n\n### Question 6\n\nCalcule **2/5 de 30**.\n\n➡️ **12**\n\n### Question 7\n\nDonne une fraction équivalente à **1/2**.\n\n➡️ **2/4**, par exemple.\n\n### Question 8\n\nLaquelle est la plus grande : **2/7 ou 5/7** ?\n\n➡️ **5/7**\n\n---\n\n# 🏆 9. DÉFI FINAL\n\nUne chocolaterie possède **120 chocolats**.\n\nLe matin, elle vend **3/5** de son stock.\n\nL'après-midi, elle vend **1/4 du stock initial**.\n\n### Questions\n\n**1. Combien de chocolats sont vendus le matin ?**\n\n**2. Combien sont vendus l'après-midi ?**\n\n**3. Combien de chocolats ont été vendus au total ?**\n\n**4. Combien reste-t-il de chocolats ?**\n\n### Correction\n\n#### Matin\n\n**3/5 de 120**\n\n**120 ÷ 5 = 24**\n\n**24 × 3 = 72**\n\nDonc **72 chocolats** sont vendus le matin.\n\n#### Après-midi\n\n**1/4 de 120**\n\n**120 ÷ 4 = 30**\n\nDonc **30 chocolats** sont vendus l'après-midi.\n\n#### Total vendu\n\n**72 + 30 = 102**\n\n#### Reste\n\n**120 − 102 = 18**\n\n### ✅ Réponse finale\n\n**72 chocolats** vendus le matin.\n\n**30 chocolats** vendus l'après-midi.\n\n**102 chocolats** vendus au total.\n\n**18 chocolats** restent.\n\n---\n\n# ⭐ 10. BILAN DU CHAPITRE\n\nÀ la fin de ce chapitre, l'élève doit savoir :\n\n☑ définir une fraction ;\n\n☑ identifier numérateur et dénominateur ;\n\n☑ lire et écrire une fraction ;\n\n☑ représenter une fraction ;\n\n☑ reconnaître une fraction < 1, = 1 ou > 1 ;\n\n☑ calculer une fraction d'une quantité ;\n\n☑ reconnaître des fractions équivalentes simples ;\n\n☑ comparer des fractions simples ;\n\n☑ placer une fraction sur une droite graduée ;\n\n☑ résoudre des problèmes avec des fractions ;\n\n☑ expliquer sa méthode.","# MATHÉMATIQUES — 6e\n\n## Chapitre 7 — Cercles et disques\n\n**Volume horaire : 7 heures**\n\n---\n\n# 🎯 OBJECTIFS D’APPRENTISSAGE\n\nÀ la fin de ce chapitre, l’élève doit être capable de :\n\n-  reconnaître un cercle et un disque ; \n-  identifier le centre, le rayon et le diamètre ; \n-  utiliser correctement le vocabulaire du cercle ; \n-  construire un cercle à l'aide d'un compas ; \n-  tracer un rayon et un diamètre ; \n-  déterminer le diamètre à partir du rayon et inversement ; \n-  reconnaître une corde ; \n-  distinguer cercle et disque ; \n-  calculer le périmètre d'un cercle dans les situations étudiées ; \n-  calculer l'aire d'un disque dans les situations étudiées ; \n-  résoudre des problèmes simples faisant intervenir cercles et disques. \n\n---\n\n# 1. 📖 COURS\n\n## 1.1. Qu'est-ce qu'un cercle ?\n\nUn **cercle** est l'ensemble des points situés à la même distance d'un point appelé **centre**.\n\nCette distance est appelée **rayon**.\n\n### Exemple\n\nSi O est le centre du cercle et si A est un point du cercle, alors :\n\n**OA** est un rayon.\n\nTous les rayons d'un même cercle ont la même longueur.\n\n---\n\n# 1.2. Le centre\n\nLe **centre** est le point situé au milieu du cercle.\n\nOn le représente généralement par une lettre majuscule, souvent **O**.\n\n### Exemple\n\nUn cercle de centre O peut être appelé :\n\n**cercle de centre O**\n\n---\n\n# 1.3. Le rayon\n\nUn **rayon** est un segment qui relie le centre du cercle à un point quelconque du cercle.\n\nSi A appartient au cercle de centre O :\n\n**[OA]** est un rayon.\n\nOn note sa longueur :\n\n**OA**\n\n### Exemple\n\nSi :\n\n**OA = 4 cm**\n\nalors le rayon du cercle est :\n\n**r = 4 cm**\n\n---\n\n# 1.4. Le diamètre\n\nUn **diamètre** est un segment qui :\n\n-  passe par le centre ; \n-  relie deux points du cercle. \n\n### Exemple\n\nSi A et B sont sur le cercle et si le segment [AB] passe par O, alors [AB] est un diamètre.\n\nLe diamètre est deux fois plus grand que le rayon.\n\n### Relation fondamentale\n\n**d = 2 × r**\n\net :\n\n**r = d ÷ 2**\n\n---\n\n# 1.5. Exemple\n\nSi le rayon d'un cercle est :\n\n**r = 5 cm**\n\nalors :\n\n**d = 2 × 5 = 10 cm**\n\nSi le diamètre est :\n\n**d = 14 cm**\n\nalors :\n\n**r = 14 ÷ 2 = 7 cm**\n\n---\n\n# 1.6. La corde\n\nUne **corde** est un segment dont les extrémités appartiennent au cercle.\n\nUne corde ne passe pas nécessairement par le centre.\n\n### Cas particulier\n\nUn diamètre est une **corde particulière** : c'est une corde qui passe par le centre.\n\n---\n\n# 1.7. Cercle et disque : différence\n\nIl est très important de ne pas les confondre.\n\n### Cercle\n\nLe cercle correspond uniquement à la **ligne qui délimite** la figure.\n\n### Disque\n\nLe disque correspond à **toute la surface située à l'intérieur du cercle**, y compris sa frontière.\n\n### Exemple\n\nUne pièce de monnaie peut être modélisée par un **disque**.\n\nLe bord de la pièce correspond à un **cercle**.\n\n---\n\n# 1.8. Construire un cercle\n\nPour construire un cercle, on utilise un **compas**.\n\n### Méthode\n\nPour construire un cercle de centre O et de rayon 4 cm :\n\n1.  place le point O ; \n2.  ouvre le compas à 4 cm ; \n3.  place la pointe sèche du compas sur O ; \n4.  fais tourner le compas autour de O ; \n5.  trace le cercle. \n\nTous les points du cercle sont alors à **4 cm de O**.\n\n---\n\n# 1.9. Vérifier un rayon\n\nSi A appartient au cercle de centre O et que le rayon vaut 5 cm :\n\n**OA = 5 cm**\n\nSi B appartient également au cercle :\n\n**OB = 5 cm**\n\nDonc :\n\n**OA = OB**\n\nTous les rayons d'un même cercle ont la même longueur.\n\n---\n\n# 1.10. Périmètre du cercle\n\nLe périmètre d'un cercle est la longueur de la ligne qui forme le cercle.\n\nOn l'appelle également parfois **circonférence**.\n\nLa formule est :\n\n**P = 2 × π × r**\n\nOn peut également utiliser :\n\n**P = π × d**\n\navec :\n\n**π ≈ 3,14**\n\n### Exemple\n\nUn cercle possède un rayon de 5 cm.\n\nAlors :\n\n**P = 2 × 3,14 × 5**\n\n**P = 31,4 cm**\n\n---\n\n# 1.11. Aire du disque\n\nL'aire d'un disque est la surface qu'il contient.\n\nLa formule est :\n\n**A = π × r²**\n\noù **r** est le rayon.\n\n### Exemple\n\nUn disque possède un rayon de 4 cm.\n\nAlors :\n\n**A = 3,14 × 4²**\n\n**A = 3,14 × 16**\n\n**A = 50,24 cm²**\n\n---\n\n# 1.12. Attention aux unités\n\nLe périmètre est une **longueur**.\n\nIl s'exprime donc en :\n\n-  mm ; \n-  cm ; \n-  m ; \n-  km. \n\nL'aire est une **surface**.\n\nElle s'exprime donc en :\n\n-  cm² ; \n-  m² ; \n-  km². \n\n### Exemple\n\n**P = 20 cm** est une longueur.\n\n**A = 20 cm²** est une aire.\n\nIl ne faut pas les confondre.\n\n---\n\n# 1.13. Utiliser le diamètre\n\nLorsque le diamètre est connu, on peut utiliser directement :\n\n**P = π × d**\n\n### Exemple\n\nUn cercle possède un diamètre de 10 cm.\n\nAlors :\n\n**P = 3,14 × 10**\n\n**P = 31,4 cm**\n\nOn obtient le même résultat qu'avec :\n\n**P = 2 × π × r**\n\npuisque :\n\n**r = 5 cm**.\n\n---\n\n# 1.14. Situations de la vie courante\n\nLes cercles et disques sont présents dans de nombreux objets :\n\n-  roues ; \n-  pièces de monnaie ; \n-  assiettes ; \n-  horloges ; \n-  couvercles ; \n-  plateaux ; \n-  CD/DVD ; \n-  rouleaux ; \n-  tables rondes. \n\nLes mathématiques permettent de calculer leur périmètre ou leur surface.\n\n---\n\n# 🧠 À RETENIR\n\n### Cercle\n\nLigne dont tous les points sont à la même distance du centre.\n\n### Rayon\n\n**r**\n\nDistance entre le centre et un point du cercle.\n\n### Diamètre\n\n**d = 2r**\n\n### Corde\n\nSegment reliant deux points du cercle.\n\n### Périmètre\n\n**P = 2πr**\n\nou\n\n**P = πd**\n\n### Aire du disque\n\n**A = πr²**\n\n### Valeur utilisée\n\n**π ≈ 3,14**\n\n---\n\n# ✏️ 2. EXERCICES D'APPLICATION\n\n## Exercice 1 — Vocabulaire\n\nComplète :\n\n1.  Le point central d'un cercle est appelé le \\_\\_\\_\\_\\_\\_. \n2.  La distance entre le centre et un point du cercle est le \\_\\_\\_\\_\\_\\_. \n3.  Un segment passant par le centre et reliant deux points du cercle est un \\_\\_\\_\\_\\_\\_. \n4.  Un segment reliant deux points du cercle est une \\_\\_\\_\\_\\_\\_. \n\n---\n\n## Exercice 2 — Rayon et diamètre\n\nComplète :\n\na) r = 3 cm → d = ...\n\nb) r = 6 cm → d = ...\n\nc) r = 8 cm → d = ...\n\nd) d = 10 cm → r = ...\n\ne) d = 18 cm → r = ...\n\n---\n\n## Exercice 3 — Construction\n\nConstruis :\n\n1.  un point O ; \n2.  un cercle de centre O et de rayon 4 cm ; \n3.  un rayon [OA] ; \n4.  un diamètre [BC]. \n\n---\n\n## Exercice 4 — Périmètre\n\nCalcule le périmètre d'un cercle de rayon :\n\na) 2 cm\n\nb) 5 cm\n\nc) 10 cm\n\nPrends **π = 3,14**.\n\n---\n\n# 🔵 3. RENFORCEMENT\n\n## Exercice 5 — Aire\n\nCalcule l'aire d'un disque de rayon :\n\na) 2 cm\n\nb) 3 cm\n\nc) 5 cm\n\nUtilise :\n\n**A = πr²**\n\navec **π = 3,14**.\n\n---\n\n## Exercice 6 — Diamètre\n\nUn cercle possède un diamètre de **12 cm**.\n\n1.  Détermine son rayon. \n2.  Calcule son périmètre. \n3.  Calcule l'aire du disque correspondant. \n\n---\n\n## Exercice 7 — Comparaison\n\nDeux cercles ont pour rayons :\n\n**r₁ = 3 cm**\n\n**r₂ = 6 cm**\n\n1.  Quel cercle possède le plus grand diamètre ? \n2.  Calcule les deux diamètres. \n3.  Calcule les deux périmètres. \n\n---\n\n## Exercice 8 — Vrai ou faux ?\n\nIndique si chaque affirmation est vraie ou fausse.\n\na) Tous les rayons d'un même cercle ont la même longueur.\n\nb) Le diamètre est la moitié du rayon.\n\nc) Un diamètre passe par le centre.\n\nd) Une corde passe toujours par le centre.\n\ne) Un disque représente la surface intérieure du cercle.\n\n---\n\n# 🔴 4. PROBLÈMES\n\n## Problème 1 — Une roue\n\nUne roue possède un diamètre de **60 cm**.\n\nOn prend :\n\n**π = 3,14**\n\n1.  Calcule son rayon. \n2.  Calcule la longueur de son bord. \n3.  Quelle distance parcourt approximativement la roue en un tour ? \n\n---\n\n## Problème 2 — Une table ronde\n\nUne table ronde possède un rayon de **70 cm**.\n\n1.  Calcule son diamètre. \n2.  Calcule la longueur de son bord. \n3.  Calcule l'aire de sa surface. \n\n---\n\n## Problème 3 — Une pièce circulaire\n\nUne pièce possède un rayon de **1,5 cm**.\n\nCalcule :\n\n1.  son diamètre ; \n2.  son périmètre ; \n3.  l'aire de sa surface. \n\n---\n\n# 📝 5. QCM\n\n### Question 1\n\nLe point situé au centre d'un cercle est appelé :\n\nA. le diamètre\n\nB. le rayon\n\nC. le centre\n\nD. la corde\n\n**Réponse : C**\n\n---\n\n### Question 2\n\nSi le rayon vaut 5 cm, le diamètre vaut :\n\nA. 2,5 cm\n\nB. 5 cm\n\nC. 10 cm\n\nD. 25 cm\n\n**Réponse : C**\n\n---\n\n### Question 3\n\nQuel segment passe nécessairement par le centre ?\n\nA. Un rayon\n\nB. Un diamètre\n\nC. Une corde quelconque\n\nD. Aucun\n\n**Réponse : B**\n\n---\n\n### Question 4\n\nLa formule du périmètre d'un cercle est :\n\nA. πr²\n\nB. 2πr\n\nC. r²\n\nD. 2r\n\n**Réponse : B**\n\n---\n\n### Question 5\n\nLa formule de l'aire d'un disque est :\n\nA. 2πr\n\nB. πd\n\nC. πr²\n\nD. 2r²\n\n**Réponse : C**\n\n---\n\n### Question 6\n\nSi r = 4 cm, l'aire du disque est :\n\nA. 12,56 cm²\n\nB. 25,12 cm²\n\nC. 50,24 cm²\n\nD. 100,48 cm²\n\n**Réponse : C**\n\n---\n\n### Question 7\n\nUn disque représente :\n\nA. uniquement le bord\n\nB. uniquement le centre\n\nC. la surface intérieure et sa frontière\n\nD. uniquement un diamètre\n\n**Réponse : C**\n\n---\n\n### Question 8\n\nSi le diamètre est 20 cm, le rayon vaut :\n\nA. 5 cm\n\nB. 10 cm\n\nC. 20 cm\n\nD. 40 cm\n\n**Réponse : B**\n\n---\n\n# ✅ 6. CORRECTION EXPLIQUÉE DU QCM\n\n### Q1 → C\n\nLe point central du cercle est son **centre**.\n\n### Q2 → C\n\nLe diamètre vaut deux fois le rayon :\n\n**d = 2 × 5 = 10 cm**\n\n### Q3 → B\n\nUn diamètre relie deux points du cercle en passant par le centre.\n\n### Q4 → B\n\nLe périmètre est :\n\n**P = 2πr**\n\n### Q5 → C\n\nL'aire du disque est :\n\n**A = πr²**\n\n### Q6 → C\n\n**A = 3,14 × 4²**\n\n**A = 3,14 × 16**\n\n**A = 50,24 cm²**\n\n### Q7 → C\n\nLe disque correspond à la surface située à l'intérieur du cercle, frontière comprise.\n\n### Q8 → B\n\n**r = d ÷ 2**\n\nDonc :\n\n**r = 20 ÷ 2 = 10 cm**\n\n---\n\n# 📋 7. FICHE MÉMO\n\n## 🔵 CERCLES ET DISQUES — 6e\n\n### Vocabulaire\n\n**O** → centre\n\n**r** → rayon\n\n**d** → diamètre\n\n**[AB]** → corde si A et B sont sur le cercle\n\n### Relations\n\n**d = 2r**\n\n**r = d ÷ 2**\n\n### Périmètre du cercle\n\n**P = 2πr**\n\nou\n\n**P = πd**\n\n### Aire du disque\n\n**A = πr²**\n\n### Valeur usuelle\n\n**π ≈ 3,14**\n\n### Attention\n\nPérimètre → unité de longueur :\n\n**cm, m...**\n\nAire → unité carrée :\n\n**cm², m²...**\n\n---\n\n# 🎮 8. QUIZ — TEST RAPIDE\n\n### Question 1\n\nComment appelle-t-on le point au centre du cercle ?\n\n➡️ **Le centre**\n\n### Question 2\n\nComment appelle-t-on la distance entre le centre et le cercle ?\n\n➡️ **Le rayon**\n\n### Question 3\n\nSi r = 7 cm, combien vaut d ?\n\n➡️ **14 cm**\n\n### Question 4\n\nSi d = 18 cm, combien vaut r ?\n\n➡️ **9 cm**\n\n### Question 5\n\nQuelle est la formule du périmètre ?\n\n➡️ **P = 2πr**\n\n### Question 6\n\nQuelle est la formule de l'aire du disque ?\n\n➡️ **A = πr²**\n\n### Question 7\n\nUn diamètre passe-t-il par le centre ?\n\n➡️ **Oui**\n\n### Question 8\n\nUne corde passe-t-elle toujours par le centre ?\n\n➡️ **Non**\n\n### Question 9\n\nQuelle est la différence entre cercle et disque ?\n\n➡️ **Le cercle est la ligne frontière ; le disque représente la surface intérieure délimitée par cette ligne.**\n\n---\n\n# 🏆 9. DÉFI FINAL\n\nUne chocolaterie possède un moule circulaire de **20 cm de diamètre**.\n\nOn prend :\n\n**π = 3,14**\n\n### Questions\n\n1.  Quel est son rayon ? \n2.  Quelle est la longueur du bord du moule ? \n3.  Quelle est sa surface ? \n4.  Si on veut recouvrir entièrement la surface avec du chocolat, quelle surface doit-on recouvrir ? \n\n### Correction\n\n### 1. Rayon\n\n**r = 20 ÷ 2**\n\n**r = 10 cm**\n\n### 2. Périmètre\n\n**P = π × d**\n\n**P = 3,14 × 20**\n\n**P = 62,8 cm**\n\n### 3. Aire\n\n**A = πr²**\n\n**A = 3,14 × 10²**\n\n**A = 3,14 × 100**\n\n**A = 314 cm²**\n\n### 4. Surface à recouvrir\n\nLa surface correspond à l'aire du disque :\n\n**314 cm²**\n\n---\n\n# ⭐ 10. BILAN DU CHAPITRE\n\nL'élève doit savoir :\n\n☑ définir un cercle ;\n\n☑ définir un disque ;\n\n☑ identifier le centre ;\n\n☑ identifier le rayon ;\n\n☑ identifier le diamètre ;\n\n☑ reconnaître une corde ;\n\n☑ utiliser la relation **d = 2r** ;\n\n☑ construire un cercle au compas ;\n\n☑ calculer le périmètre d'un cercle ;\n\n☑ calculer l'aire d'un disque ;\n\n☑ choisir les bonnes unités ;\n\n☑ résoudre des problèmes liés aux cercles et aux disques.","# MATHÉMATIQUES — 6e\n\n## Chapitre 8 — Angles\n\n**Volume horaire : 7 heures**\n\n---\n\n# 🎯 OBJECTIFS D’APPRENTISSAGE\n\nÀ la fin de ce chapitre, l’élève doit être capable de :\n\n-  reconnaître et nommer un angle ; \n-  identifier le sommet et les côtés d'un angle ; \n-  utiliser correctement la notation d'un angle ; \n-  mesurer un angle avec un rapporteur ; \n-  construire un angle de mesure donnée ; \n-  distinguer angle aigu, droit, obtus et plat ; \n-  comparer des angles ; \n-  reconnaître deux angles complémentaires ou supplémentaires dans des situations simples ; \n-  utiliser les propriétés des angles droits et plats ; \n-  résoudre des problèmes simples faisant intervenir des angles. \n\n---\n\n# 1. 📖 COURS\n\n## 1.1. Qu'est-ce qu'un angle ?\n\nUn **angle** est une figure formée par **deux demi-droites ayant la même origine**.\n\nCette origine commune est appelée le **sommet de l'angle**.\n\nLes deux demi-droites sont appelées les **côtés de l'angle**.\n\n### Exemple\n\nSi les demi-droites **[OA)** et **[OB)** ont la même origine O, elles forment l'angle :\n\n**AÔB**\n\nLe sommet est :\n\n**O**\n\nLes côtés sont :\n\n**[OA)** et **[OB)**.\n\n---\n\n# 1.2. Notation d'un angle\n\nUn angle se note généralement avec **trois lettres**.\n\nDans :\n\n**AÔB**\n\nla lettre du milieu correspond toujours au **sommet**.\n\nDonc :\n\n**AÔB**\n\net :\n\n**BÔA**\n\ndésignent le même angle.\n\n⚠️ Il faut toujours identifier correctement la lettre du sommet.\n\n---\n\n# 1.3. Le sommet et les côtés\n\nDans l'angle **AÔB** :\n\n- **O** est le sommet ; \n- **[OA)** est un côté ; \n- **[OB)** est l'autre côté. \n\n### À retenir\n\nDans une notation à trois lettres, **la lettre du milieu est le sommet**.\n\n---\n\n# 1.4. Mesurer un angle\n\nPour mesurer un angle, on utilise un **rapporteur**.\n\nL'unité utilisée est le **degré**, noté :\n\n**°**\n\nPar exemple :\n\n**45°**\n\nse lit :\n\n**quarante-cinq degrés**.\n\n---\n\n# 1.5. Utiliser correctement un rapporteur\n\nPour mesurer l'angle **AÔB** :\n\n### Étape 1\n\nPlace le centre du rapporteur sur le sommet **O**.\n\n### Étape 2\n\nAligne la ligne de base du rapporteur avec l'un des côtés de l'angle.\n\n### Étape 3\n\nRepère la graduation **0°** située du côté du premier côté de l'angle.\n\n### Étape 4\n\nLis la graduation correspondant au deuxième côté.\n\n### Étape 5\n\nÉcris la mesure avec le symbole **°**.\n\n---\n\n# 1.6. Les deux échelles du rapporteur\n\nUn rapporteur possède généralement **deux échelles graduées**.\n\nIl faut choisir celle qui commence à **0° du côté où commence ton angle**.\n\n### Erreur fréquente\n\nUn élève peut lire 130° alors que l'angle mesure en réalité 50°.\n\nPour éviter cette erreur, il faut toujours vérifier :\n\n> **L'angle doit commencer à la graduation 0°.**\n\n---\n\n# 1.7. L'angle nul\n\nUn **angle nul** mesure :\n\n**0°**\n\nSes deux côtés sont confondus.\n\n---\n\n# 1.8. L'angle aigu\n\nUn angle **aigu** mesure :\n\n**plus de 0° et moins de 90°**.\n\nExemples :\n\n**20°**\n\n**45°**\n\n**70°**\n\nsont des angles aigus.\n\n---\n\n# 1.9. L'angle droit\n\nUn angle droit mesure exactement :\n\n**90°**\n\nIl est souvent représenté par un petit carré au niveau du sommet.\n\n### Exemple\n\nLes coins d'une feuille rectangulaire sont des angles droits.\n\n---\n\n# 1.10. L'angle obtus\n\nUn angle **obtus** mesure :\n\n**plus de 90° et moins de 180°**.\n\nExemples :\n\n**100°**\n\n**120°**\n\n**150°**\n\nsont des angles obtus.\n\n---\n\n# 1.11. L'angle plat\n\nUn angle plat mesure :\n\n**180°**\n\nSes deux côtés sont dans des directions opposées et forment une ligne droite.\n\n---\n\n# 1.12. Tableau récapitulatif\n\n| Type d'angle | Mesure             |\n| ------------ | ------------------ |\n| Angle nul    | 0°                 |\n| Angle aigu   | 0° < angle < 90°   |\n| Angle droit  | 90°                |\n| Angle obtus  | 90° < angle < 180° |\n| Angle plat   | 180°               |\n\n---\n\n# 1.13. Comparer des angles\n\nPour comparer deux angles, on peut comparer leurs mesures.\n\n### Exemple\n\n**A = 45°**\n\n**B = 70°**\n\nAlors :\n\n**A < B**\n\nL'angle B est plus grand que l'angle A.\n\n---\n\n# 1.14. Construire un angle\n\nPour construire un angle de **60°** :\n\n### Étape 1\n\nTrace une demi-droite **[OA)**.\n\n### Étape 2\n\nPlace le centre du rapporteur sur **O**.\n\n### Étape 3\n\nAligne la base du rapporteur sur **[OA)**.\n\n### Étape 4\n\nRepère la graduation **60°**.\n\n### Étape 5\n\nMarque un point B à cette graduation.\n\n### Étape 6\n\nTrace la demi-droite **[OB)**.\n\nTu obtiens :\n\n**AÔB = 60°**\n\n---\n\n# 1.15. Angles complémentaires\n\nDeux angles sont **complémentaires** lorsque leur somme vaut :\n\n**90°**\n\n### Exemple\n\nUn angle mesure 30°.\n\nSon complément vaut :\n\n**90° − 30° = 60°**\n\nLes angles 30° et 60° sont donc complémentaires.\n\n---\n\n# 1.16. Angles supplémentaires\n\nDeux angles sont **supplémentaires** lorsque leur somme vaut :\n\n**180°**\n\n### Exemple\n\nUn angle mesure 120°.\n\nSon supplémentaire vaut :\n\n**180° − 120° = 60°**\n\n---\n\n# 1.17. Cas d'un angle droit\n\nSi deux angles forment ensemble un angle droit :\n\n**leur somme vaut 90°**.\n\n### Exemple\n\nSi un premier angle mesure 35° :\n\n**90° − 35° = 55°**\n\nLe deuxième angle mesure donc **55°**.\n\n---\n\n# 1.18. Cas d'un angle plat\n\nSi deux angles forment ensemble un angle plat :\n\n**leur somme vaut 180°**.\n\n### Exemple\n\nUn angle mesure 75°.\n\nL'autre mesure :\n\n**180° − 75° = 105°**\n\n---\n\n# 🧠 À RETENIR\n\nUn angle est formé par deux demi-droites ayant la même origine.\n\nDans **AÔB** :\n\n**O = sommet**\n\n**[OA)** et **[OB)** = côtés.\n\n### Mesures importantes\n\n**Angle nul = 0°**\n\n**Angle aigu : < 90°**\n\n**Angle droit = 90°**\n\n**Angle obtus : entre 90° et 180°**\n\n**Angle plat = 180°**\n\n### Relations\n\nAngles complémentaires :\n\n**somme = 90°**\n\nAngles supplémentaires :\n\n**somme = 180°**\n\n---\n\n# ✏️ 2. EXERCICES D'APPLICATION\n\n## Exercice 1 — Vocabulaire\n\nDans l'angle **AÔB** :\n\n1.  Quel est le sommet ? \n2.  Quels sont les deux côtés ? \n3.  Comment peut-on également nommer cet angle ? \n\n---\n\n## Exercice 2 — Identifier les angles\n\nIndique le type de chaque angle :\n\na) 35°\n\nb) 90°\n\nc) 125°\n\nd) 180°\n\ne) 60°\n\nf) 15°\n\n---\n\n## Exercice 3 — Comparaison\n\nCompare :\n\na) 45° et 70°\n\nb) 90° et 90°\n\nc) 120° et 80°\n\nd) 150° et 180°\n\nUtilise **<, > ou =**.\n\n---\n\n## Exercice 4 — Mesure\n\nÀ l'aide d'un rapporteur, construis :\n\na) un angle de 30° ;\n\nb) un angle de 60° ;\n\nc) un angle de 90° ;\n\nd) un angle de 120°.\n\n---\n\n# 🔵 3. RENFORCEMENT\n\n## Exercice 5 — Complémentaires\n\nComplète :\n\na) 30° + ... = 90°\n\nb) 45° + ... = 90°\n\nc) 65° + ... = 90°\n\nd) 15° + ... = 90°\n\n---\n\n## Exercice 6 — Supplémentaires\n\nComplète :\n\na) 30° + ... = 180°\n\nb) 75° + ... = 180°\n\nc) 120° + ... = 180°\n\nd) 160° + ... = 180°\n\n---\n\n## Exercice 7\n\nUn angle mesure **37°**.\n\n1.  Est-il aigu, droit ou obtus ? \n2.  Quelle est la mesure de son complément ? \n3.  Quelle est la mesure de son supplémentaire ? \n\n---\n\n## Exercice 8\n\nUn angle mesure **115°**.\n\n1.  Quel est son type ? \n2.  Peut-il avoir un complément positif ? \n3.  Quelle est la mesure de son supplémentaire ? \n\n---\n\n# 🔴 4. PROBLÈMES\n\n## Problème 1\n\nUne porte est ouverte de **70°**.\n\n1.  Quel type d'angle forme-t-elle avec le mur ? \n2.  Combien manque-t-il de degrés pour obtenir un angle droit ? \n3.  Combien manque-t-il de degrés pour obtenir un angle plat ? \n\n---\n\n## Problème 2\n\nDeux angles complémentaires sont formés.\n\nLe premier mesure **28°**.\n\nQuelle est la mesure du deuxième ?\n\n---\n\n## Problème 3\n\nDeux angles supplémentaires sont formés.\n\nLe premier mesure **132°**.\n\nQuelle est la mesure du deuxième ?\n\n---\n\n# 📝 5. QCM\n\n### Question 1\n\nUn angle est formé par :\n\nA. deux segments quelconques\n\nB. deux demi-droites ayant la même origine\n\nC. deux cercles\n\nD. trois points obligatoirement alignés\n\n**Réponse : B**\n\n---\n\n### Question 2\n\nDans l'angle AÔB, le sommet est :\n\nA. A\n\nB. B\n\nC. O\n\nD. AB\n\n**Réponse : C**\n\n---\n\n### Question 3\n\nUn angle droit mesure :\n\nA. 45°\n\nB. 60°\n\nC. 90°\n\nD. 180°\n\n**Réponse : C**\n\n---\n\n### Question 4\n\nUn angle de 35° est :\n\nA. nul\n\nB. aigu\n\nC. droit\n\nD. obtus\n\n**Réponse : B**\n\n---\n\n### Question 5\n\nUn angle de 120° est :\n\nA. aigu\n\nB. droit\n\nC. obtus\n\nD. plat\n\n**Réponse : C**\n\n---\n\n### Question 6\n\nUn angle plat mesure :\n\nA. 90°\n\nB. 120°\n\nC. 180°\n\nD. 360°\n\n**Réponse : C**\n\n---\n\n### Question 7\n\nDeux angles complémentaires ont une somme de :\n\nA. 45°\n\nB. 90°\n\nC. 180°\n\nD. 360°\n\n**Réponse : B**\n\n---\n\n### Question 8\n\nDeux angles supplémentaires ont une somme de :\n\nA. 90°\n\nB. 100°\n\nC. 180°\n\nD. 360°\n\n**Réponse : C**\n\n---\n\n### Question 9\n\nPour mesurer un angle, on utilise principalement :\n\nA. une règle\n\nB. un compas\n\nC. un rapporteur\n\nD. une équerre uniquement\n\n**Réponse : C**\n\n---\n\n# ✅ 6. CORRECTION EXPLIQUÉE DU QCM\n\n**Q1 → B**\n\nUn angle est formé par deux demi-droites ayant la même origine.\n\n**Q2 → C**\n\nDans une notation à trois lettres, **la lettre du milieu est le sommet**.\n\n**Q3 → C**\n\nPar définition :\n\n**angle droit = 90°**\n\n**Q4 → B**\n\n35° est compris entre 0° et 90° : c'est donc un angle aigu.\n\n**Q5 → C**\n\n120° est compris entre 90° et 180° : c'est un angle obtus.\n\n**Q6 → C**\n\nUn angle plat mesure exactement 180°.\n\n**Q7 → B**\n\nDeux angles complémentaires ont une somme de 90°.\n\n**Q8 → C**\n\nDeux angles supplémentaires ont une somme de 180°.\n\n**Q9 → C**\n\nLe rapporteur permet de mesurer et de construire des angles.\n\n---\n\n# 📋 7. FICHE MÉMO\n\n## 📐 ANGLES — 6e\n\n### Vocabulaire\n\nUn angle possède :\n\n-  un **sommet** ; \n-  deux **côtés**. \n\nDans **AÔB** :\n\n**O = sommet**\n\n**[OA)** et **[OB)** = côtés.\n\n### Types d'angles\n\n**0°** → nul\n\n**entre 0° et 90°** → aigu\n\n**90°** → droit\n\n**entre 90° et 180°** → obtus\n\n**180°** → plat\n\n### Relations\n\nComplémentaires :\n\n**A + B = 90°**\n\nSupplémentaires :\n\n**A + B = 180°**\n\n### Instrument\n\n**Rapporteur → mesurer/construire un angle**\n\n---\n\n# 🎮 8. QUIZ — TEST RAPIDE\n\n**1. Combien de côtés possède un angle ?**\n\n➡️ **Deux demi-droites.**\n\n**2. Quel est le sommet de l'angle BÔC ?**\n\n➡️ **O**\n\n**3. Combien mesure un angle droit ?**\n\n➡️ **90°**\n\n**4. 45° est-il aigu ou obtus ?**\n\n➡️ **Aigu**\n\n**5. 130° est-il aigu ou obtus ?**\n\n➡️ **Obtus**\n\n**6. Combien mesure un angle plat ?**\n\n➡️ **180°**\n\n**7. Deux angles complémentaires totalisent combien ?**\n\n➡️ **90°**\n\n**8. Deux angles supplémentaires totalisent combien ?**\n\n➡️ **180°**\n\n**9. Quel instrument utilise-t-on pour mesurer un angle ?**\n\n➡️ **Le rapporteur.**\n\n**10. Quel est le complément de 25° ?**\n\n➡️ **65°**\n\n---\n\n# 🏆 9. DÉFI FINAL\n\nOn considère trois angles :\n\n- **A = 35°** \n- **B = 55°** \n- **C = 125°** \n\n### Questions\n\n1.  A et B sont-ils complémentaires ? \n2.  A et C sont-ils supplémentaires ? \n3.  Quel est le type de chacun des trois angles ? \n4.  Quel est le complément de A ? \n5.  Quel est le supplémentaire de C ? \n\n### Correction\n\n### 1. A + B\n\n**35° + 55° = 90°**\n\nDonc A et B sont **complémentaires**.\n\n### 2. A + C\n\n**35° + 125° = 160°**\n\nIls ne sont donc **pas supplémentaires**.\n\n### 3. Types\n\n**35° → aigu**\n\n**55° → aigu**\n\n**125° → obtus**\n\n### 4. Complément de A\n\n**90° − 35° = 55°**\n\n### 5. Supplémentaire de C\n\n**180° − 125° = 55°**\n\n---\n\n# ⭐ 10. BILAN DU CHAPITRE\n\nL'élève doit savoir :\n\n☑ définir un angle ;\n\n☑ identifier son sommet et ses côtés ;\n\n☑ nommer correctement un angle ;\n\n☑ utiliser un rapporteur ;\n\n☑ mesurer un angle ;\n\n☑ construire un angle donné ;\n\n☑ reconnaître un angle aigu ;\n\n☑ reconnaître un angle droit ;\n\n☑ reconnaître un angle obtus ;\n\n☑ reconnaître un angle plat ;\n\n☑ connaître les angles complémentaires ;\n\n☑ connaître les angles supplémentaires ;\n\n☑ résoudre des problèmes simples sur les angles.","# MATHÉMATIQUES — 6e\n\n## Chapitre 9 — Triangles\n\n**Volume horaire : 7 heures**\n\n---\n\n# 🎯 OBJECTIFS D’APPRENTISSAGE\n\nÀ la fin de ce chapitre, l’élève doit être capable de :\n\n-  reconnaître et définir un triangle ; \n-  identifier ses sommets, ses côtés et ses angles ; \n-  nommer correctement un triangle ; \n-  construire un triangle à partir de longueurs données ; \n-  connaître les principaux types de triangles ; \n-  reconnaître un triangle équilatéral ; \n-  reconnaître un triangle isocèle ; \n-  reconnaître un triangle rectangle ; \n-  reconnaître un triangle quelconque ; \n-  utiliser les propriétés élémentaires des triangles ; \n-  calculer le périmètre d'un triangle ; \n-  reconnaître la hauteur d'un triangle dans des situations simples ; \n-  résoudre des problèmes portant sur les triangles. \n\n---\n\n# 1. 📖 COURS\n\n## 1.1. Qu'est-ce qu'un triangle ?\n\nUn **triangle** est une figure géométrique formée de :\n\n- **3 côtés** ; \n- **3 sommets** ; \n- **3 angles**. \n\n### Exemple\n\nUn triangle peut être nommé :\n\n**ABC**\n\nSes sommets sont :\n\n**A, B et C**\n\nSes côtés sont :\n\n**[AB]**\n\n**[BC]**\n\n**[AC]**\n\nSes angles sont :\n\n**Â, B̂ et Ĉ**\n\n---\n\n# 1.2. Comment nommer un triangle ?\n\nPour nommer un triangle, on utilise les lettres de ses trois sommets.\n\n### Exemple\n\nUn triangle possédant les sommets A, B et C est appelé :\n\n**triangle ABC**\n\nOn peut également l'appeler :\n\n**triangle BCA**\n\nou :\n\n**triangle CAB**\n\nà condition de conserver les trois sommets.\n\n---\n\n# 1.3. Construire un triangle\n\nPour construire un triangle à partir de trois longueurs, on peut utiliser :\n\n-  une règle graduée ; \n-  un compas. \n\n### Exemple\n\nConstruisons un triangle ABC tel que :\n\n**AB = 5 cm**\n\n**AC = 4 cm**\n\n**BC = 3 cm**\n\n### Méthode\n\n1.  Trace le segment [AB] de longueur 5 cm. \n2.  Avec le compas, trace un arc de cercle de centre A et de rayon 4 cm. \n3.  Avec le compas, trace un arc de cercle de centre B et de rayon 3 cm. \n4.  Le point d'intersection des deux arcs est C. \n5.  Relie A à C et B à C. \n\nLe triangle ABC est construit.\n\n---\n\n# 1.4. Triangle quelconque\n\nUn **triangle quelconque** est un triangle dont les trois côtés peuvent avoir des longueurs différentes.\n\n### Exemple\n\nUn triangle de côtés :\n\n**3 cm ; 4 cm ; 5 cm**\n\nest un triangle dont les trois côtés sont différents.\n\n---\n\n# 1.5. Triangle équilatéral\n\nUn **triangle équilatéral** possède **trois côtés de même longueur**.\n\nSi :\n\n**AB = BC = CA**\n\nalors ABC est équilatéral.\n\n### Propriété\n\nLes trois angles d'un triangle équilatéral ont également la même mesure.\n\nChacun mesure :\n\n**60°**\n\n---\n\n# 1.6. Triangle isocèle\n\nUn **triangle isocèle** possède **deux côtés de même longueur**.\n\n### Exemple\n\nSi :\n\n**AB = AC**\n\nalors ABC est isocèle en A.\n\nDans ce cas, les angles opposés aux côtés égaux sont égaux.\n\nDonc :\n\n**B̂ = Ĉ**\n\n---\n\n# 1.7. Triangle rectangle\n\nUn **triangle rectangle** possède un angle droit.\n\nUn angle droit mesure :\n\n**90°**\n\n### Exemple\n\nSi l'angle A mesure 90°, alors ABC est un triangle rectangle en A.\n\nLe côté opposé à l'angle droit est appelé **hypoténuse**.\n\n---\n\n# 1.8. Triangle rectangle isocèle\n\nUn triangle peut être à la fois :\n\n-  rectangle ; \n-  isocèle. \n\nIl possède alors :\n\n-  un angle droit ; \n-  deux côtés de même longueur. \n\nLes deux autres angles sont égaux.\n\n---\n\n# 1.9. Triangle et somme des angles\n\nDans tout triangle, la somme des mesures des trois angles est :\n\n**180°**\n\n### Exemple\n\nUn triangle possède deux angles :\n\n**50°** et **60°**.\n\nLe troisième angle vaut :\n\n**180° − 50° − 60°**\n\n**= 70°**\n\n---\n\n# 1.10. Calculer un angle inconnu\n\n### Exemple\n\nDans un triangle ABC :\n\n**Â = 40°**\n\n**B̂ = 75°**\n\nCalculons Ĉ.\n\nOn sait que :\n\n**Â + B̂ + Ĉ = 180°**\n\nDonc :\n\n**Ĉ = 180° − 40° − 75°**\n\n**Ĉ = 65°**\n\n---\n\n# 1.11. Périmètre d'un triangle\n\nLe périmètre d'un triangle est la somme des longueurs de ses trois côtés.\n\n### Formule\n\n**P = AB + BC + CA**\n\n### Exemple\n\nUn triangle possède les côtés :\n\n**5 cm ; 7 cm ; 9 cm**\n\nSon périmètre est :\n\n**P = 5 + 7 + 9**\n\n**P = 21 cm**\n\n---\n\n# 1.12. Hauteur d'un triangle\n\nUne **hauteur** est une droite ou un segment qui part d'un sommet et est **perpendiculaire** au côté opposé, ou à son prolongement.\n\n### Exemple\n\nDans un triangle ABC, la hauteur issue de A est perpendiculaire à la droite (BC).\n\nElle permet notamment de calculer l'aire d'un triangle.\n\n---\n\n# 1.13. Aire d'un triangle\n\nL'aire d'un triangle se calcule avec :\n\n**A = (base × hauteur) ÷ 2**\n\n### Exemple\n\nUn triangle possède :\n\n-  une base de 8 cm ; \n-  une hauteur correspondante de 5 cm. \n\nAlors :\n\n**A = (8 × 5) ÷ 2**\n\n**A = 40 ÷ 2**\n\n**A = 20 cm²**\n\n---\n\n# 1.14. Reconnaître un triangle à partir de ses côtés\n\n### Trois côtés égaux\n\n→ triangle **équilatéral**\n\n### Deux côtés égaux\n\n→ triangle **isocèle**\n\n### Trois côtés différents\n\n→ triangle **quelconque**\n\n### Un angle droit\n\n→ triangle **rectangle**\n\n⚠️ Un triangle peut appartenir à plusieurs catégories.\n\nPar exemple :\n\n**triangle rectangle isocèle**.\n\n---\n\n# 🧠 À RETENIR\n\nUn triangle possède :\n\n**3 côtés**\n\n**3 sommets**\n\n**3 angles**\n\n### Types selon les côtés\n\n**Équilatéral → 3 côtés égaux**\n\n**Isocèle → 2 côtés égaux**\n\n**Quelconque → 3 côtés différents**\n\n### Selon les angles\n\n**Rectangle → un angle de 90°**\n\n### Propriété fondamentale\n\nLa somme des angles d'un triangle est :\n\n**180°**\n\n### Périmètre\n\n**P = a + b + c**\n\n### Aire\n\n**A = (base × hauteur) ÷ 2**\n\n---\n\n# ✏️ 2. EXERCICES D'APPLICATION\n\n## Exercice 1 — Vocabulaire\n\nDans le triangle ABC :\n\n1.  Combien y a-t-il de sommets ? \n2.  Quels sont les trois côtés ? \n3.  Combien y a-t-il d'angles ? \n4.  Comment appelle-t-on l'angle situé au sommet B ? \n\n---\n\n## Exercice 2 — Identifier les triangles\n\nIndique le type de triangle correspondant.\n\na) côtés : 5 cm, 5 cm, 5 cm\n\nb) côtés : 6 cm, 6 cm, 4 cm\n\nc) côtés : 3 cm, 4 cm, 5 cm\n\nd) triangle possédant un angle de 90°\n\n---\n\n## Exercice 3 — Périmètre\n\nCalcule le périmètre d'un triangle dont les côtés mesurent :\n\na) 4 cm, 5 cm et 6 cm\n\nb) 7 cm, 7 cm et 5 cm\n\nc) 8 cm, 9 cm et 10 cm\n\n---\n\n## Exercice 4 — Angles\n\nDans un triangle :\n\n**Â = 50°**\n\n**B̂ = 60°**\n\nCalcule **Ĉ**.\n\n---\n\n# 🔵 3. RENFORCEMENT\n\n## Exercice 5\n\nUn triangle isocèle possède deux côtés de **8 cm** et une base de **5 cm**.\n\n1.  Calcule son périmètre. \n2.  Quels sont les côtés de même longueur ? \n\n---\n\n## Exercice 6\n\nUn triangle possède les angles :\n\n**35° ; 65° ; x°**\n\nCalcule x.\n\n---\n\n## Exercice 7 — Aire\n\nUn triangle possède :\n\n**base = 12 cm**\n\n**hauteur = 7 cm**\n\nCalcule son aire.\n\n---\n\n## Exercice 8 — Reconnaissance\n\nUn triangle possède trois côtés de :\n\n**6 cm, 6 cm et 6 cm**\n\n1.  Quel est son type ? \n2.  Quelle est la mesure de chacun de ses angles ? \n\n---\n\n# 🔴 4. PROBLÈMES\n\n## Problème 1 — Terrain triangulaire\n\nUn terrain triangulaire possède des côtés de :\n\n**25 m, 30 m et 35 m**.\n\n1.  Calcule son périmètre. \n2.  Si son propriétaire souhaite installer une clôture tout autour, quelle longueur de clôture doit-il prévoir ? \n\n---\n\n## Problème 2 — Triangle et angles\n\nDans un triangle ABC :\n\n**Â = 48°**\n\n**B̂ = 72°**\n\n1.  Calcule Ĉ. \n2.  Le triangle peut-il être rectangle ? \n3.  Justifie ta réponse. \n\n---\n\n## Problème 3 — Aire\n\nUn panneau triangulaire possède une base de **2 m** et une hauteur de **1,5 m**.\n\nCalcule son aire.\n\n---\n\n# 📝 5. QCM\n\n### Question 1\n\nCombien de côtés possède un triangle ?\n\nA. 2\n\nB. 3\n\nC. 4\n\nD. 5\n\n**Réponse : B**\n\n---\n\n### Question 2\n\nUn triangle équilatéral possède :\n\nA. deux côtés égaux\n\nB. trois côtés égaux\n\nC. aucun côté égal\n\nD. quatre côtés\n\n**Réponse : B**\n\n---\n\n### Question 3\n\nUn triangle isocèle possède :\n\nA. trois côtés égaux obligatoirement\n\nB. deux côtés de même longueur\n\nC. quatre côtés\n\nD. aucun angle\n\n**Réponse : B**\n\n---\n\n### Question 4\n\nUn triangle rectangle possède :\n\nA. un angle de 45°\n\nB. un angle de 60°\n\nC. un angle de 90°\n\nD. un angle de 180°\n\n**Réponse : C**\n\n---\n\n### Question 5\n\nLa somme des angles d'un triangle est :\n\nA. 90°\n\nB. 180°\n\nC. 270°\n\nD. 360°\n\n**Réponse : B**\n\n---\n\n### Question 6\n\nUn triangle possède des côtés de 5 cm, 6 cm et 7 cm. Son périmètre est :\n\nA. 11 cm\n\nB. 17 cm\n\nC. 18 cm\n\nD. 21 cm\n\n**Réponse : C**\n\n---\n\n### Question 7\n\nL'aire d'un triangle est :\n\nA. base × hauteur\n\nB. (base × hauteur) ÷ 2\n\nC. base + hauteur\n\nD. 2 × base × hauteur\n\n**Réponse : B**\n\n---\n\n### Question 8\n\nSi deux angles d'un triangle mesurent 40° et 80°, le troisième mesure :\n\nA. 40°\n\nB. 50°\n\nC. 60°\n\nD. 80°\n\n**Réponse : C**\n\n---\n\n# ✅ 6. CORRECTION EXPLIQUÉE DU QCM\n\n### Q1 → B\n\nUn triangle possède **3 côtés** et **3 sommets**.\n\n### Q2 → B\n\nUn triangle équilatéral possède trois côtés de même longueur.\n\n### Q3 → B\n\nUn triangle isocèle possède au moins deux côtés de même longueur.\n\n### Q4 → C\n\nUn triangle rectangle possède un angle droit :\n\n**90°**\n\n### Q5 → B\n\nLa somme des trois angles d'un triangle est toujours :\n\n**180°**\n\n### Q6 → C\n\n**P = 5 + 6 + 7**\n\n**P = 18 cm**\n\n### Q7 → B\n\nLa formule de l'aire est :\n\n**A = (base × hauteur) ÷ 2**\n\n### Q8 → C\n\n**180° − 40° − 80° = 60°**\n\nLe troisième angle mesure donc **60°**.\n\n---\n\n# 📋 7. FICHE MÉMO\n\n## 🔺 TRIANGLES — 6e\n\n### Vocabulaire\n\nUn triangle possède :\n\n**3 sommets**\n\n**3 côtés**\n\n**3 angles**\n\n### Types\n\n**Équilatéral → 3 côtés égaux**\n\n**Isocèle → 2 côtés égaux**\n\n**Quelconque → 3 côtés différents**\n\n**Rectangle → un angle de 90°**\n\n### Angles\n\n**A + B + C = 180°**\n\n### Périmètre\n\n**P = a + b + c**\n\n### Aire\n\n**A = (base × hauteur) ÷ 2**\n\n### Construction\n\nPour construire un triangle avec trois longueurs données, on peut utiliser une **règle** et un **compas**.\n\n---\n\n# 🎮 8. QUIZ — TEST RAPIDE\n\n**1. Combien de côtés possède un triangle ?**\n\n➡️ **3**\n\n**2. Combien de sommets possède-t-il ?**\n\n➡️ **3**\n\n**3. Quel triangle possède trois côtés égaux ?**\n\n➡️ **Le triangle équilatéral.**\n\n**4. Quel triangle possède deux côtés égaux ?**\n\n➡️ **Le triangle isocèle.**\n\n**5. Quel triangle possède un angle de 90° ?**\n\n➡️ **Le triangle rectangle.**\n\n**6. Quelle est la somme des angles d'un triangle ?**\n\n➡️ **180°**\n\n**7. Calcule le troisième angle si les deux autres mesurent 40° et 70°.**\n\n➡️ **70°**\n\n**8. Un triangle possède des côtés de 5, 6 et 8 cm. Quel est son périmètre ?**\n\n➡️ **19 cm**\n\n**9. Quelle est la formule de l'aire ?**\n\n➡️ **(base × hauteur) ÷ 2**\n\n---\n\n# 🏆 9. DÉFI FINAL\n\nUn triangle ABC possède :\n\n**AB = 8 cm**\n\n**AC = 8 cm**\n\n**BC = 6 cm**\n\net :\n\n**Â = 40°**\n\n**B̂ = 70°**\n\n### Questions\n\n1.  Quel type de triangle est ABC selon ses côtés ? \n2.  Calcule son troisième angle. \n3.  Calcule son périmètre. \n4.  Si la hauteur relative à BC mesure 7,5 cm, calcule son aire. \n\n### Correction\n\n### 1. Type\n\n**AB = AC = 8 cm**\n\nDeux côtés sont égaux.\n\nDonc le triangle est **isocèle en A**.\n\n### 2. Troisième angle\n\n**Ĉ = 180° − 40° − 70°**\n\n**Ĉ = 70°**\n\n### 3. Périmètre\n\n**P = 8 + 8 + 6**\n\n**P = 22 cm**\n\n### 4. Aire\n\nLa base est **BC = 6 cm**.\n\nLa hauteur correspondante est **7,5 cm**.\n\nDonc :\n\n**A = (6 × 7,5) ÷ 2**\n\n**A = 45 ÷ 2**\n\n**A = 22,5 cm²**\n\n---\n\n# ⭐ 10. BILAN DU CHAPITRE\n\nL'élève doit savoir :\n\n☑ définir un triangle ;\n\n☑ identifier ses sommets, côtés et angles ;\n\n☑ nommer un triangle ;\n\n☑ construire un triangle ;\n\n☑ reconnaître un triangle équilatéral ;\n\n☑ reconnaître un triangle isocèle ;\n\n☑ reconnaître un triangle rectangle ;\n\n☑ reconnaître un triangle quelconque ;\n\n☑ utiliser la somme des angles d'un triangle ;\n\n☑ calculer le périmètre d'un triangle ;\n\n☑ calculer son aire dans les situations étudiées ;\n\n☑ résoudre des problèmes sur les triangles.","# MATHÉMATIQUES — 6e\n\n## Chapitre 10 : PROPORTIONNALITÉ — 7 h\n\n---\n\n## 🎯 1. OBJECTIFS D’APPRENTISSAGE\n\nÀ la fin de ce chapitre, l’élève doit être capable de :\n\n-  reconnaître une situation de proportionnalité ; \n-  compléter un tableau de proportionnalité ; \n-  utiliser le **coefficient de proportionnalité** ; \n-  calculer une quatrième proportionnelle ; \n-  résoudre des problèmes simples de proportionnalité ; \n-  utiliser la proportionnalité dans des situations de la vie courante ; \n-  vérifier si deux grandeurs sont proportionnelles. \n\n---\n\n# 📖 2. COURS\n\n## A. Qu’est-ce qu’une situation de proportionnalité ?\n\nDeux grandeurs sont **proportionnelles** lorsque l’on peut passer d’une grandeur à l’autre en multipliant toujours par **un même nombre**.\n\n### Exemple\n\nUn cahier coûte **500 F CFA**.\n\n| Nombre de cahiers | 1   | 2     | 3     | 4     | 5     |\n| ----------------- | --- | ----- | ----- | ----- | ----- |\n| Prix (F CFA)      | 500 | 1 000 | 1 500 | 2 000 | 2 500 |\n\nPour passer du nombre de cahiers au prix, on multiplie toujours par **500**.\n\n```math\nPrix = nombre\\ de\\ cahiers \\times 500\n```\n\nLes deux grandeurs sont donc **proportionnelles**.\n\n---\n\n## B. Le coefficient de proportionnalité\n\nLe nombre par lequel on multiplie une grandeur pour obtenir l’autre s’appelle le **coefficient de proportionnalité**.\n\n### Exemple\n\n3 bouteilles coûtent 1 500 F.\n\nLe prix d’une bouteille est :\n\n```math\n1500 \\div 3 = 500\n```\n\nLe coefficient de proportionnalité est donc **500**.\n\nOn peut écrire :\n\n```math\nPrix = Nombre \\times 500\n```\n\n---\n\n## C. Reconnaître un tableau de proportionnalité\n\nConsidérons :\n\n| Quantité | 2   | 4     | 6     | 8     |\n| -------- | --- | ----- | ----- | ----- |\n| Prix     | 600 | 1 200 | 1 800 | 2 400 |\n\nOn vérifie :\n\n```math\n600\\div2=300\n```\n\n```math\n1200\\div4=300\n```\n\n```math\n1800\\div6=300\n```\n\n```math\n2400\\div8=300\n```\n\nLe quotient est toujours le même.\n\n👉 C’est donc un **tableau de proportionnalité**.\n\n---\n\n# D. Compléter un tableau de proportionnalité\n\n### Exemple\n\n| Nombre de stylos | 2   | 5 | 8 | 10 |\n| ---------------- | --- | - | - | -- |\n| Prix (F CFA)     | 600 | ? | ? | ?  |\n\nUn stylo coûte :\n\n```math\n600\\div2=300\n```\n\nDonc :\n\n-  5 stylos → `5\\times300=1500` F \n-  8 stylos → `8\\times300=2400` F \n-  10 stylos → `10\\times300=3000` F \n\nTableau complété :\n\n| Nombre de stylos | 2   | 5     | 8     | 10    |\n| ---------------- | --- | ----- | ----- | ----- |\n| Prix (F CFA)     | 600 | 1 500 | 2 400 | 3 000 |\n\n---\n\n# E. Trouver une quatrième proportionnelle\n\nOn peut avoir :\n\n| Quantité | 3   | 7 |\n| -------- | --- | - |\n| Prix     | 900 | ? |\n\n### Méthode 1 : chercher le prix d’une unité\n\n```math\n900\\div3=300\n```\n\nDonc :\n\n```math\n7\\times300=2100\n```\n\n👉 Le prix de 7 objets est **2 100 F CFA**.\n\n---\n\n### Méthode 2 : utiliser un passage par une quantité connue\n\nSi :\n\n```math\n3\\rightarrow900\n```\n\nalors :\n\n```math\n6\\rightarrow1800\n```\n\ncar 6 est le double de 3.\n\nPuis :\n\n```math\n7\\rightarrow2100\n```\n\n---\n\n# F. La règle de trois\n\nÀ ce niveau, on peut aussi utiliser une méthode appelée **règle de trois**.\n\n### Exemple\n\n4 kg de cacao coûtent 6 000 F.\n\nCombien coûtent 7 kg ?\n\nOn écrit :\n\n```math\n4\\ kg \\rightarrow 6000\\ F\n```\n\n```math\n7\\ kg \\rightarrow x\n```\n\nOn cherche le prix d'un kilogramme :\n\n```math\n6000\\div4=1500\n```\n\nDonc :\n\n```math\n7\\times1500=10500\n```\n\n### Réponse :\n\n**7 kg coûtent 10 500 F CFA.**\n\n---\n\n# G. Proportionnalité et recettes 🍫\n\nLa proportionnalité est très utilisée dans les recettes.\n\n### Exemple\n\nPour fabriquer une préparation, il faut :\n\n-  200 g de chocolat pour 4 personnes. \n\nCombien faut-il de chocolat pour 10 personnes ?\n\nPour une personne :\n\n```math\n200\\div4=50g\n```\n\nPour 10 personnes :\n\n```math\n50\\times10=500g\n```\n\n👉 Il faut **500 g de chocolat**.\n\n---\n\n# H. Attention : toutes les situations ne sont pas proportionnelles\n\n### Exemple\n\nUne course en taxi coûte :\n\n-  500 F de prise en charge ; \n-  puis 100 F par kilomètre. \n\nPour 1 km :\n\n```math\n500+100=600\n```\n\nPour 2 km :\n\n```math\n500+200=700\n```\n\nPour 3 km :\n\n```math\n500+300=800\n```\n\n| Distance | 1 km | 2 km | 3 km |\n| -------- | ---- | ---- | ---- |\n| Prix     | 600  | 700  | 800  |\n\nCe n’est **pas** une situation de proportionnalité.\n\nPourquoi ?\n\nParce que :\n\n```math\n600\\div1\\neq700\\div2\n```\n\nLe quotient n’est pas constant.\n\n---\n\n# 🧠 À RETENIR\n\nUne situation est proportionnelle lorsque :\n\n> **on multiplie toujours par le même nombre pour passer d'une grandeur à l'autre.**\n\nCe nombre est appelé :\n\n### ⭐ coefficient de proportionnalité\n\n---\n\n# ✏️ 3. EXERCICES D’APPLICATION\n\n## Exercice 1\n\nUn cahier coûte 750 F CFA.\n\n1.  Combien coûtent 2 cahiers ? \n2.  Combien coûtent 5 cahiers ? \n3.  Combien coûtent 8 cahiers ? \n\n---\n\n## Exercice 2\n\nComplète le tableau :\n\n| Nombre de bouteilles | 1   | 3 | 5 | 10 |\n| -------------------- | --- | - | - | -- |\n| Prix (F CFA)         | 400 | ? | ? | ?  |\n\n---\n\n## Exercice 3\n\nComplète :\n\n| Masse de cacao | 2 kg    | 4 kg | 7 kg | 10 kg |\n| -------------- | ------- | ---- | ---- | ----- |\n| Prix           | 3 000 F | ?    | ?    | ?     |\n\n---\n\n## Exercice 4\n\nPour faire 6 crêpes, il faut 300 g de farine.\n\nCombien faut-il de farine pour :\n\na) 12 crêpes ?\n\nb) 18 crêpes ?\n\nc) 24 crêpes ?\n\n---\n\n## Exercice 5\n\nUn élève parcourt 4 km en 1 heure à vitesse constante.\n\nCombien de kilomètres parcourt-il en :\n\na) 2 heures ?\n\nb) 3 heures ?\n\nc) 5 heures ?\n\n---\n\n# 🔵 4. RENFORCEMENT\n\n## Exercice 6\n\nOn donne le tableau :\n\n| Nombre de tablettes | 2     | 4     | 6     | 10     |\n| ------------------- | ----- | ----- | ----- | ------ |\n| Prix (F CFA)        | 2 000 | 4 000 | 6 000 | 10 000 |\n\n1.  Les grandeurs sont-elles proportionnelles ? \n2.  Quel est le coefficient de proportionnalité ? \n3.  Combien coûtent 15 tablettes ? \n\n---\n\n## Exercice 7\n\nUne voiture consomme 6 litres de carburant pour parcourir 100 km.\n\nQuelle quantité de carburant faut-il pour parcourir :\n\na) 200 km ?\n\nb) 300 km ?\n\nc) 500 km ?\n\n---\n\n## Exercice 8\n\nPour préparer une boisson, on utilise 2 litres d’eau pour 5 personnes.\n\nQuelle quantité d’eau faut-il pour :\n\na) 10 personnes ?\n\nb) 15 personnes ?\n\nc) 20 personnes ?\n\n---\n\n# 🔴 5. PROBLÈMES\n\n## Problème 1 — Au marché 🛒\n\nUn commerçant vend 3 kg de riz à 2 100 F CFA.\n\n### Questions\n\n1.  Quel est le prix d’un kilogramme ? \n2.  Combien coûtent 5 kg ? \n3.  Combien coûtent 8 kg ? \n\n---\n\n## Problème 2 — Chocolaterie 🍫\n\nPour fabriquer 20 petites tablettes de chocolat, un chocolatier utilise 1 kg de chocolat.\n\nCombien de chocolat faut-il pour fabriquer :\n\n-  40 tablettes ? \n-  60 tablettes ? \n-  100 tablettes ? \n\n---\n\n## Problème 3 — Sortie scolaire 🚌\n\nUn bus transporte 45 élèves.\n\nPour une sortie, il faut transporter 135 élèves.\n\nCombien de trajets identiques faut-il effectuer ?\n\n---\n\n# 📝 6. QCM\n\n### Question 1\n\nUne situation de proportionnalité utilise :\n\nA. toujours une addition\n\nB. toujours le même coefficient multiplicateur\n\nC. toujours une soustraction\n\nD. des nombres au hasard\n\n---\n\n### Question 2\n\n4 stylos coûtent 1 200 F.\n\nQuel est le prix d’un stylo ?\n\nA. 200 F\n\nB. 250 F\n\nC. 300 F\n\nD. 400 F\n\n---\n\n### Question 3\n\nSi 1 cahier coûte 500 F, combien coûtent 6 cahiers ?\n\nA. 2 500 F\n\nB. 3 000 F\n\nC. 3 500 F\n\nD. 4 000 F\n\n---\n\n### Question 4\n\nLe tableau suivant est-il proportionnel ?\n\n| Quantité | 2   | 4     | 6     |\n| -------- | --- | ----- | ----- |\n| Prix     | 500 | 1 000 | 1 500 |\n\nA. Oui\n\nB. Non\n\nC. Impossible à savoir\n\nD. Seulement pour 2\n\n---\n\n### Question 5\n\n5 kg de riz coûtent 3 000 F.\n\nCombien coûte 1 kg ?\n\nA. 500 F\n\nB. 600 F\n\nC. 700 F\n\nD. 800 F\n\n---\n\n### Question 6\n\nSi 3 cahiers coûtent 900 F, combien coûtent 9 cahiers ?\n\nA. 1 800 F\n\nB. 2 100 F\n\nC. 2 700 F\n\nD. 3 000 F\n\n---\n\n### Question 7\n\nQuelle situation est proportionnelle ?\n\nA. Une course avec 500 F de prise en charge + 100 F/km\n\nB. Le prix d'objets identiques vendus au même prix unitaire\n\nC. L'âge d'un enfant et sa taille\n\nD. Le nombre d'années et la date de naissance\n\n---\n\n### Question 8\n\nPour 4 personnes, une recette demande 200 g de farine.\n\nPour 8 personnes, il faut :\n\nA. 250 g\n\nB. 300 g\n\nC. 400 g\n\nD. 800 g\n\n---\n\n# ✅ 7. CORRECTION EXPLIQUÉE DU QCM\n\n### Q1 → **B** ✅\n\nDans une situation de proportionnalité, on utilise toujours le même coefficient.\n\n---\n\n### Q2 → **C** ✅\n\n```math\n1200\\div4=300\n```\n\nUn stylo coûte **300 F**.\n\n---\n\n### Q3 → **B** ✅\n\n```math\n500\\times6=3000\n```\n\nDonc **3 000 F**.\n\n---\n\n### Q4 → **A** ✅\n\n```math\n500\\div2=250\n```\n\n```math\n1000\\div4=250\n```\n\n```math\n1500\\div6=250\n```\n\nLe coefficient est toujours 250.\n\n---\n\n### Q5 → **B** ✅\n\n```math\n3000\\div5=600\n```\n\nUn kilogramme coûte **600 F**.\n\n---\n\n### Q6 → **C** ✅\n\n3 cahiers → 900 F.\n\n9 cahiers représentent 3 fois plus :\n\n```math\n900\\times3=2700\n```\n\nDonc **2 700 F**.\n\n---\n\n### Q7 → **B** ✅\n\nLorsque chaque objet possède le même prix unitaire, le prix total est proportionnel au nombre d'objets.\n\n---\n\n### Q8 → **C** ✅\n\n8 personnes représentent le double de 4 personnes.\n\n```math\n200\\times2=400g\n```\n\nDonc **400 g**.\n\n---\n\n# 📋 8. FICHE MÉMO\n\n## ⭐ PROPORTIONNALITÉ\n\n### Définition\n\nDeux grandeurs sont proportionnelles lorsqu'on passe de l'une à l'autre en multipliant toujours par le même nombre.\n\n### Coefficient\n\n```math\nCoefficient=\\frac{Grandeur\\ obtenue}{Grandeur\\ de\\ départ}\n```\n\n### Pour trouver une valeur manquante\n\n**Méthode 1 :** trouver la valeur correspondant à 1 unité.\n\nExemple :\n\n```math\n4\\rightarrow800\n```\n\n```math\n1\\rightarrow800\\div4=200\n```\n\nPuis :\n\n```math\n7\\rightarrow7\\times200=1400\n```\n\n### À vérifier\n\nDans un tableau de proportionnalité :\n\n```math\n\\frac{a}{b}=\\frac{c}{d}\n```\n\nou les quotients correspondants sont égaux.\n\n### ⚠️ Attention\n\nUne situation n'est pas proportionnelle simplement parce qu'elle contient des nombres.\n\nIl faut que **le coefficient reste constant**.\n\n---\n\n# 🎮 9. QUIZ\n\n### Niveau 1 🟢\n\n**1.** 1 bouteille coûte 250 F. Combien coûtent 4 bouteilles ?\n\n**2.** 3 kg coûtent 1 500 F. Combien coûte 1 kg ?\n\n**3.** Si 1 objet coûte 800 F, combien coûtent 5 objets ?\n\n---\n\n### Niveau 2 🟠\n\n**4.** 6 cahiers coûtent 3 600 F. Combien coûtent 10 cahiers ?\n\n**5.** Une recette pour 4 personnes demande 300 g de farine. Quelle quantité faut-il pour 12 personnes ?\n\n**6.** 5 m de tissu coûtent 4 000 F. Combien coûtent 8 m ?\n\n---\n\n### Niveau 3 🔴\n\n**7.** Un vendeur vend 8 kg de cacao à 12 000 F. Quel est le prix de 15 kg ?\n\n**8.** Pour 10 élèves, une activité nécessite 2 litres d'eau. Combien faut-il pour 35 élèves ?\n\n**9.** Explique pourquoi le tableau suivant n'est pas proportionnel :\n\n| Quantité | 2   | 4     | 6     |\n| -------- | --- | ----- | ----- |\n| Prix     | 500 | 1 100 | 1 500 |\n\n---\n\n# 🏆 10. DÉFI FINAL\n\n## 🍫 Le défi du jeune chocolatier\n\nTu dois préparer des sachets contenant des chocolats.\n\nPour **6 sachets**, il faut **900 g de chocolat**.\n\n### Questions\n\n1.  Combien faut-il de chocolat pour 1 sachet ? \n2.  Combien faut-il pour 10 sachets ? \n3.  Combien faut-il pour 20 sachets ? \n4.  Avec 3 kg de chocolat, combien de sachets peux-tu préparer ? \n5.  Explique la méthode utilisée. \n\n### ⭐ Défi supplémentaire\n\nUn client commande **35 sachets**.\n\nQuelle quantité de chocolat faut-il prévoir ?\n\n---\n\n# 🎯 BILAN DU CHAPITRE\n\nÀ la fin de ce chapitre, je sais :\n\n☐ reconnaître une situation de proportionnalité ;\n\n☐ identifier un coefficient de proportionnalité ;\n\n☐ compléter un tableau ;\n\n☐ calculer une quatrième proportionnelle ;\n\n☐ utiliser une valeur pour 1 unité ;\n\n☐ résoudre un problème de proportionnalité ;\n\n☐ expliquer pourquoi une situation est ou n'est pas proportionnelle.\n\n### ⭐ La règle essentielle\n\n> **PROPORTIONNALITÉ = MÊME COEFFICIENT**"];
const chapterMeta=[
 {ordre:6,title:'Fractions'},
 {ordre:7,title:'Cercles et disques'},
 {ordre:8,title:'Angles'},
 {ordre:9,title:'Triangles'},
 {ordre:10,title:'Proportionnalité'}
];

function section(src, startRe, endRe){
 const s=src.search(startRe);
 if(s<0) return '';
 const rest=src.slice(s);
 const e=rest.search(endRe);
 return (e<0?rest:rest.slice(0,e)).trim();
}
function parseQcm(text){
 const questions=[]; const re=/### Question\s+(\d+)\s+([\s\S]*?)(?=\n---\n|\n### Question\s+\d+|$)/g; let m;
 while((m=re.exec(text))){
  const block=m[2].trim();
  const q=block.match(/^([\s\S]*?)(?=\nA\. )/);
  if(!q) continue;
  const choices=[];
  for(const letter of ['A','B','C','D']){
   const cm=block.match(new RegExp('\\n'+letter+'\\. ([^\\n]+)'));
   if(cm) choices.push(cm[1].trim());
  }
  const ans=block.match(/\*\*Réponse\s*:\s*\*\*([ABCD])/i);
  if(!ans||choices.length<2) continue;
  questions.push({id:'q'+m[1],type:'qcm',enonce:q[1].trim(),choix:choices,bonnesReponses:['ABCD'.indexOf(ans[1].toUpperCase())],reponseAttendue:'',explication:'Correction expliquée fournie dans le contenu source.',points:1});
 }
 return questions;
}
function parseDoc(src,meta){
 const course=section(src,/# (?:1\. 📖 COURS|📖 2\. COURS)/,/# ✏️/);
 const exercises=section(src,/# ✏️/,/# 🔵/);
 const reinforcement=section(src,/# 🔵/,/# 📝/);
 const qcm=section(src,/# 📝/,/# 📋/);
 const revision=section(src,/# 📋/);
 return {ordre:meta.ordre,title:meta.title,course,exercises,reinforcement,qcm,revision};
}
const chapters=sources.map((s,i)=>parseDoc(s,chapterMeta[i]));

async function deleteAllForChapter(chapId){
 const snap=await db.collection('ca_ressources').where('chapitreId','==',chapId).get();
 if(snap.empty) return 0;
 let deleted=0,batch=db.batch(),ops=0;
 for(const doc of snap.docs){
  batch.delete(doc.ref); ops++; deleted++;
  if(ops===450){await batch.commit();batch=db.batch();ops=0;}
 }
 if(ops) await batch.commit();
 return deleted;
}
async function main(){
 let oldResourcesDeleted=0,resourcesCreated=0,chaptersProcessed=0;
 for(const c of chapters){
  const chapId='6e_math_ch'+String(c.ordre).padStart(2,'0');
  const chap=await db.collection('ca_chapitres').doc(chapId).get();
  if(!chap.exists){console.warn('Chapitre absent',chapId);continue;}
  oldResourcesDeleted+=await deleteAllForChapter(chapId);
  await chap.ref.set({description:c.title+' — contenu pédagogique complet fourni par l’utilisateur.',dateMaj:FieldValue.serverTimestamp()},{merge:true});
  const questions=parseQcm(c.qcm);
  const resources=[
   {type:'cours',titre:'Cours complet — '+c.title,ordre:1,contenu:c.course},
   {type:'exercices',titre:'Exercices et corrections — '+c.title,ordre:2,contenu:c.exercises},
   {type:'renforcement',titre:'Renforcement et problèmes — '+c.title,ordre:3,contenu:c.reinforcement},
   {type:'quiz',titre:'QCM — '+c.title,ordre:4,contenu:c.qcm,questions},
   {type:'revision',titre:'Fiche de révision et quiz — '+c.title,ordre:5,contenu:c.revision}
  ];
  for(const r of resources){
   await db.collection('ca_ressources').add({
    type:r.type,titre:r.titre,ordre:r.ordre,chapitreId:chapId,niveau:'6e',matiereId:'math',
    ecoleId:'',contenu:r.contenu||'',imagesUrls:[],pdfUrl:'',videoYoutubeId:'',
    enonce:'',solution:'',difficulte:r.type==='quiz'?2:1,ressourceLieeId:'',
    questions:r.questions||[],dureeMinutes:r.type==='quiz'?12:30,examen:false,
    annee:2026,serie:'',actif:false,ressourceNationale:true,
    auteur:'Sentinel CI — contenu fourni par utilisateur',
    dateMaj:FieldValue.serverTimestamp(),dateCreation:FieldValue.serverTimestamp()
   });
   resourcesCreated++;
  }
  chaptersProcessed++;
 }
 await db.collection('ca_parametres').doc('version').set({
  version:FieldValue.increment(1),dateMaj:FieldValue.serverTimestamp(),
  derniereRessourceNationale:'MATH_6E_LOT_CH6_CH10_REPLACEMENT'
 },{merge:true});
 console.log(JSON.stringify({ok:true,mode:'full_replacement',chaptersProcessed,oldResourcesDeleted,resourcesCreated,expectedResources:chaptersProcessed*5,publication:'draft_only'},null,2));
}
main().catch(e=>{console.error('ENRICH_MATH6E_USER_LOT_CH6_CH10_ERROR',e.stack||e);process.exit(1);});
